import sys

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]
best = 0
for i in range(n):
    for j in range(i + 1, n):
        if not all(a[p] < a[i] and a[p] < a[j] for p in range(i + 1, j)):
            continue
        for k in range(j + 1, n):
            if all(a[q] < a[j] and a[q] < a[k] for q in range(j + 1, k)):
                best = max(best, k - i)
print(best)

